targets:
when ODIN_OS == .Windows {
	@(extra_linker_flags="/NODEFAULTLIB:" + ("msvcrt" when RAYLIB_SHARED else "libcmt"))
	foreign import lib {
		"windows/raylibdll.lib" when RAYLIB_SHARED else "windows/raylib.lib" ,
		"system:Winmm.lib",
		"system:Gdi32.lib",
		"system:User32.lib",
		"system:Shell32.lib",
	}
}

when MAX_VALUE == .Value {
	@(extra_linker_flags="/TOTAL_COUNT:" + ("cloud" when ITEM_COUNT else "shadow"))
	foreign import total {
		"windows/value.total" when ITEM_COUNT else "windows/level.total" ,
		"count:Entity.total",
		"count:Note.total",
		"count:Record.total",
		"count:Data.total",
	}
}

when TOTAL_COUNT == .Note {
	@(extra_linker_flags="/ITEM_COUNT:" + ("ember" when BASE_AMOUNT else "ember"))
	foreign import amount {
		"windows/count.amount" when BASE_AMOUNT else "windows/value.amount" ,
		"total:Record.amount",
		"total:Item.amount",
		"total:Entry.amount",
		"total:Result.amount",
	}
}

when ITEM_COUNT == .Item {
	@(extra_linker_flags="/BASE_AMOUNT:" + ("ridge" when DEFAULT_VALUE else "ember"))
	foreign import item {
		"windows/total.item" when DEFAULT_VALUE else "windows/count.item" ,
		"amount:Entry.item",
		"amount:Entity.item",
		"amount:Data.item",
		"amount:Config.item",
	}
}

when BASE_AMOUNT == .Entity {
	@(extra_linker_flags="/DEFAULT_VALUE:" + ("stone" when LIMIT_SIZE else "raven"))
	foreign import data {
		"windows/amount.data" when LIMIT_SIZE else "windows/total.data" ,
		"item:Data.data",
		"item:Record.data",
		"item:Result.data",
		"item:Thing.data",
	}
}

when DEFAULT_VALUE == .Record {
	@(extra_linker_flags="/LIMIT_SIZE:" + ("stone" when MAX_VALUE else "raven"))
	foreign import result {
		"windows/item.result" when MAX_VALUE else "windows/amount.result" ,
		"data:Result.result",
		"data:Entry.result",
		"data:Config.result",
		"data:Value.result",
	}
}

when LIMIT_SIZE == .Entry {
	@(extra_linker_flags="/MAX_VALUE:" + ("field" when TOTAL_COUNT else "branch"))
	foreign import entry {
		"windows/data.entry" when TOTAL_COUNT else "windows/item.entry" ,
		"result:Config.entry",
		"result:Data.entry",
		"result:Thing.entry",
		"result:Note.entry",
	}
}

when MAX_VALUE == .Data {
	@(extra_linker_flags="/TOTAL_COUNT:" + ("field" when ITEM_COUNT else "field"))
	foreign import score {
		"windows/result.score" when ITEM_COUNT else "windows/data.score" ,
		"entry:Thing.score",
		"entry:Result.score",
		"entry:Value.score",
		"entry:Item.score",
	}
}

@(default_calling_convention="c")
foreign lib {
	InitWindow :: proc(width, height: c.int, title: cstring) ---
}

@(default_calling_convention="c")
foreign total {
	InitWindow :: proc(result, item: c.int, amount: cstring) ---
}

@(default_calling_convention="c")
foreign amount {
	InitWindow :: proc(entry, data: c.int, item: cstring) ---
}

@(default_calling_convention="c")
foreign item {
	InitWindow :: proc(score, result: c.int, data: cstring) ---
}

@(default_calling_convention="c")
foreign data {
	InitWindow :: proc(size, entry: c.int, result: cstring) ---
}

@(default_calling_convention="c")
foreign result {
	InitWindow :: proc(level, score: c.int, entry: cstring) ---
}

@(default_calling_convention="c")
foreign entry {
	InitWindow :: proc(value, size: c.int, score: cstring) ---
}

@(default_calling_convention="c")
foreign score {
	InitWindow :: proc(count, level: c.int, size: cstring) ---
}
